patch:
diff --git a/repro/cross-drive-ignore.js b/repro/cross-drive-ignore.js
new file mode 100644
index 0000000..ffbb1dd
--- /dev/null
+++ b/repro/cross-drive-ignore.js
@@ -0,0 +1,57 @@
+"use strict";
+/*
+ * Repro for "files on a different drive are not ignored on Windows".
+ * Simulates Windows on Linux: every require("path") / require("node:path")
+ * returns path.win32 and process.cwd() is C:\Project.
+ */
+const Module = require("node:module");
+const realPath = require("node:path");
+const winPath = realPath.win32;
+const repoRoot = realPath.resolve(__dirname, "..");
+
+const origLoad = Module._load;
+Module._load = function(request, ...rest) {
+    if (request === "path" || request === "node:path") {
+        return winPath;
+    }
+    return origLoad.call(this, request, ...rest);
+};
+process.cwd = () => "C:\\Project";
+
+const { Linter, ESLint } = require(realPath.join(repoRoot, "lib/api"));
+
+console.log("path.win32.relative('C:\\\\Project', 'F:\\\\foo.js') =",
+    JSON.stringify(winPath.relative("C:\\Project", "F:\\foo.js")),
+    "(does not start with '..', so the outside-base-path check misses it)");
+console.log("path.win32.relative('C:\\\\Project', 'C:\\\\other\\\\foo.js') =",
+    JSON.stringify(winPath.relative("C:\\Project", "C:\\other\\foo.js")));
+console.log();
+
+const linter = new Linter({ configType: "flat" });
+const config = { rules: { "no-undef": "error" } };
+
+for (const file of ["C:\\other\\foo.js", "F:\\foo.js"]) {
+    const msgs = linter.verify("foo()", config, file);
+    console.log(`Linter#verify ${file}:`, msgs.map(m => m.ruleId || m.message));
+}
+console.log();
+
+(async () => {
+    const eslint = new ESLint({ overrideConfigFile: true, overrideConfig: config });
+
+    for (const file of ["C:\\other\\foo.js", "F:\\foo.js"]) {
+        const ignored = await eslint.isPathIgnored(file);
+        const [result] = await eslint.lintText("foo();", { filePath: file, warnIgnored: true });
+        console.log(`ESLint ${file}: isPathIgnored=${ignored}, lintText messages=`,
+            result.messages.map(m => m.ruleId || m.message));
+    }
+
+    const linterBug = linter.verify("foo()", config, "F:\\foo.js").length !== 0;
+    const eslintBug = !(await eslint.isPathIgnored("F:\\foo.js"));
+
+    console.log();
+    console.log(linterBug || eslintBug
+        ? "BUG REPRODUCED: F:\\foo.js (different drive than cwd C:\\Project) is linted instead of ignored"
+        : "Not reproduced: F:\\foo.js is ignored");
+    process.exitCode = linterBug || eslintBug ? 1 : 0;
+})();
